# WAR INTEL — reliable full-address copy + scrollable card (Watch button always reachable)
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-copy-scroll.ps1
$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'miniapp')) { Write-Host 'ERROR: run from project root' -ForegroundColor Red; exit 1 }
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'miniapp\index.html'), [Convert]::FromBase64String($b64))
Write-Host '  wrote miniapp/index.html' -ForegroundColor Green
Write-Host 'Then: git add -A; git commit -m "reliable copy + scrollable card"; git push' -ForegroundColor Cyan